5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	// ---------------------------------------------------------------------------
13	// Premium calculation
14	//
15	// Constants, helpers, and calculatePremium itself. Claim/payout calculation
16	// (deductible, cap, dragon-material and high-enchantment reimbursement
17	// clauses) is a separate concern and lives in its own section below, once
18	// implemented.
19	// ---------------------------------------------------------------------------
20	
21	const PROCESSING_FEE = 5;
22	
23	// Main items and components share one lookup: every type has a single base
24	// per-unit premium here. Where pricing behavior actually diverges (e.g. the
25	// component block discount below), that's layered on top in premiumForType
26	// rather than by splitting this table.
27	const BASE_PREMIUMS: Record<string, number> = {
28	  // main items
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  // components
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	const COMPONENT_BLOCK_SIZE = 3;
39	const COMPONENT_BLOCK_PREMIUM = 60;
40	
41	const CURSE_SURCHARGE = 0.5;
42	const HIGH_ENCHANTMENT_THRESHOLD = 5;
43	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
44	
45	const FIRST_INSURANCE_SURCHARGE = 0.1;
46	const LOYALTY_YEARS_THRESHOLD = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	const FOLLOW_UP_DISCOUNT = 0.15;
49	
50	// Guards against float drift (e.g. 100 * 1.1 === 110.00000000000001) before
51	// rounding up to the nearest whole gold piece, as the spec requires exact-G amounts.
52	const roundUpToGold = (amount: number): number => Math.ceil(Math.round(amount * 100) / 100);
53	
54	// A block discount replaces the per-unit price with one flat premium, but only
55	// when a type's count exactly matches the block size (e.g. 3 runes → 60G flat;
56	// 2 or 4 runes still price per-unit).
57	const premiumForType = (type: string, count: number): number =>
58	  count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : count * BASE_PREMIUMS[type];
59	
60	// A cursed item's surcharge is 50% of its own base premium (not the policy
61	// total), so it's calculated per item rather than per type group.
62	const curseSurchargeForItem = (item: Item): number =>
63	  item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE : 0;
64	
65	const enchantmentSurchargeForItem = (item: Item): number =>
66	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? BASE_PREMIUMS[item.type] * HIGH_ENCHANTMENT_SURCHARGE : 0;
67	
68	// Curse and high-enchantment surcharges stack additively per item (an item
69	// can be both cursed and highly enchanted), so they're summed together in a
70	// single per-item total rather than accumulated via separate traversals.
71	const itemSurcharge = (item: Item): number => curseSurchargeForItem(item) + enchantmentSurchargeForItem(item);
72	
73	const loyaltyDiscountRateFor = (customer: Customer): number =>
74	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? LOYALTY_DISCOUNT : 0;
75	
76	// A customer has a "follow-up contract" once they've received at least one
77	// prior quote, regardless of whether it converted to a policy.
78	const followUpDiscountRateFor = (previousQuoteCount: number): number =>
79	  previousQuoteCount > 0 ? FOLLOW_UP_DISCOUNT : 0;
80	
81	export const calculatePremium = (customer: Customer, items: Item[], previousQuoteCount = 0): number => {
82	  if (items.length === 0) return PROCESSING_FEE;
83	
84	  const countsByType: Record<string, number> = {};
85	  for (const item of items) {
86	    countsByType[item.type] = (countsByType[item.type] ?? 0) + 1;
87	  }
88	
89	  // "Policy base premium" per the spec: the sum of all item base premiums
90	  // (after block discounts), before any item-specific or policy-wide modifiers.
91	  const policyBasePremium = Object.entries(countsByType).reduce(
92	    (sum, [type, count]) => sum + premiumForType(type, count),
93	    0,
94	  );
95	
96	  // Item-specific modifiers (cursed, high enchantment) apply to each item's own
97	  // base premium and are summed in here, ahead of any policy-wide modifiers.
98	  const itemModifierTotal = items.reduce((sum, item) => sum + itemSurcharge(item), 0);
99	
100	  const premiumBeforePolicyModifiers = policyBasePremium + itemModifierTotal;
101	
102	  // Policy-wide modifiers (loyalty, first insurance, follow-up contract) are each
103	  // a percentage of the policy base premium, summed together rather than
104	  // compounded sequentially — per the spec's integration example, which adds
105	  // "+ 10 first insurance − 20 loyalty ... − 15 follow-up" as flat amounts.
106	  const policyWideModifierRate =
107	    FIRST_INSURANCE_SURCHARGE - loyaltyDiscountRateFor(customer) - followUpDiscountRateFor(previousQuoteCount);
108	
109	  // NOTE: policyWideModifierRate is applied against policyBasePremium (the raw
110	  // item base total), NOT against premiumBeforePolicyModifiers (which already
111	  // includes curse/enchantment surcharges). This is load-bearing: the spec's
112	  // integration example only balances when first-insurance/loyalty/follow-up
113	  // percentages are computed off the 100G item base, not the running total.
114	  const finalPremium = premiumBeforePolicyModifiers + policyBasePremium * policyWideModifierRate;
115	  return roundUpToGold(finalPremium) + PROCESSING_FEE;
116	};
117	
