119	// Claim calculation
120	// ---------------------------------------------------------------------------
121	
122	const DEDUCTIBLE = 100;
123	const CLAIM_HIGH_ENCHANTMENT_THRESHOLD = 8;
124	const CLAIM_HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
125	
126	export const calculateClaim = (item: Item, damageAmount: number): number => {
127	  // Only one reimbursement clause exists so far (high enchantment → 50%).
128	  // When a second clause (dragon-material → full reimbursement) is added,
129	  // revisit this ternary: the spec says the 50% clause takes precedence
130	  // when both apply, so the check order here will matter.
131	  const reimbursed =
132	    (item.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_THRESHOLD
133	      ? damageAmount * CLAIM_HIGH_ENCHANTMENT_REIMBURSEMENT
134	      : damageAmount;
135	  return reimbursed - DEDUCTIBLE;
136	};
